import hashlib, json
from pathlib import Path
source = Path('products/services/welfare-tender/followon-rehearsal/official-notice-refresh.json')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == 'a4d2af226911f6eb8a9c1c9b618276c5ccd471bbab6ce05b8a0df6165f1c24a2', 'Pinned official snapshot hash mismatch'
package = json.loads(raw)
releases = package.get('releases', [package])
records = []
for release in releases:
    tender = release.get('tender') or {}
    for lot in tender.get('lots') or []:
        if lot.get('id') == 'LOT-0000':
            records.append({'release_id': release.get('id'), 'ocid': release.get('ocid'), 'release_date': release.get('date'), 'tags': release.get('tag'), 'tender_status': tender.get('status'), 'lot': lot})
assert records, 'LOT-0000 missing from pinned snapshot'
print(json.dumps({'source': str(source), 'sha256': digest, 'matching_release_lots': records}, ensure_ascii=False, indent=2))
